WITH inner_cte AS ( SELECT r.MAJOR_USE_DESC, o.ORGANIZATION_NAME, COUNT(r.FCLT_ROOM_KEY) AS room_count, MIN(r.FLOOR) AS min_floor FROM FCLT_ROOMS r JOIN FCLT_ORGANIZATION o ON r.FCLT_ORGANIZATION_KEY = o.FCLT_ORGANIZATION_KEY WHERE r.AREA > 100 AND r.ACCESS_LEVEL = 1 GROUP BY r.MAJOR_USE_DESC, o.ORGANIZATION_NAME ), OrgSuperviseeStats AS ( SELECT FCLT_ORGANIZATION.ORGANIZATION_NAME, EXP(AVG(LN(SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES))) AS geometric_mean_supervisees FROM FCLT_ORGANIZATION JOIN SPACE_UNIT ON FCLT_ORGANIZATION.DLC_KEY = SPACE_UNIT.DLC_KEY JOIN SPACE_SUPERVISOR_USAGE ON SPACE_UNIT.DLC_KEY = SPACE_SUPERVISOR_USAGE.DEPT_NAMES WHERE SPACE_SUPERVISOR_USAGE.NUM_OF_SUPERVISEES > 0 GROUP BY FCLT_ORGANIZATION.ORGANIZATION_NAME ), OrgResearchVolume AS ( SELECT FCLT_ORGANIZATION.ORGANIZATION_NAME, SUM(SPACE_SUPERVISOR_USAGE.RESEARCH_VOLUME) AS total_research_volume FROM FCLT_ORGANIZATION JOIN SPACE_UNIT ON FCLT_ORGANIZATION.DLC_KEY = SPACE_UNIT.DLC_KEY JOIN SPACE_SUPERVISOR_USAGE ON SPACE_UNIT.DLC_KEY = SPACE_SUPERVISOR_USAGE.DEPT_NAMES WHERE SPACE_SUPERVISOR_USAGE.RESEARCH_VOLUME > 0 GROUP BY FCLT_ORGANIZATION.ORGANIZATION_NAME ) SELECT inner_cte.MAJOR_USE_DESC, inner_cte.ORGANIZATION_NAME, inner_cte.room_count, inner_cte.min_floor, os.geometric_mean_supervisees, orv.total_research_volume FROM inner_cte LEFT JOIN OrgSuperviseeStats os ON inner_cte.ORGANIZATION_NAME = os.ORGANIZATION_NAME LEFT JOIN OrgResearchVolume orv ON inner_cte.ORGANIZATION_NAME = orv.ORGANIZATION_NAME;